INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', 'リモートワーク', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

新型の働き方としてリモートワークが定着しつつある。通勤時間が削減され、自分のペースで業務を進められる利点がある一方、同僚との偶発的な会話が減り、孤独感を覚える社員も少なくないという。ある調査では、在宅勤務を続ける社員の生産性は出社時と大差ないという結果も出ている。とはいえ、新人教育や部署間の連携においては、対面でのやり取りが依然として重要な役割を果たしているとの指摘もある。実際、リモートワークを導入した企業の中には、新人の早期離職率が上昇したという事例を公表しているところもあるという。こうした背景から、入社直後の一定期間は出社を義務付ける企業も見られる。結局のところ、業務内容や個人の性格によって最適な働き方は異なり、一律に優劣を論じることは難しいといえるだろう。今後は、対面と非対面を組み合わせたハイブリッド型の働き方が主流になるとの見方も広がっており、各企業は試行錯誤を続けている。

【設問】
リモートワークには通勤時間の削減という利点がある。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 0, '["本文に「通勤時間が削減され、自分のペースで業務を進められる利点がある」と明記されている。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9201);
