INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', 'ミツバチと生態系', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

ミツバチは花粉を運ぶことで多くの植物の受粉を助け、農作物の生産にも大きく貢献している。しかし近年、世界各地でミツバチの数が急激に減少しており、その原因として農薬の使用や生息環境の変化、さらには気候の変動などが挙げられている。ミツバチが減少すれば、受粉を頼る作物の収穫量にも影響が及ぶ可能性がある。実際に一部の地域では、人の手で花粉を運ぶ作業を代替せざるを得なくなっているという報告もあり、農家の負担増加が懸念されている。養蜂家の中には、巣箱を都市部に移して環境の良い場所を探す試みを始めた人もいる。都市部は農薬の使用量が少なく、意外にもミツバチにとって暮らしやすい環境になりつつあるという指摘もある。実際、都市養蜂によって採れたはちみつを地元産品として販売する取り組みも各地で始まっている。生態系の小さな変化が、私たちの食生活にまで波及しうるという事実は、あらためて考えさせられる問題である。

【設問】
ミツバチの減少の原因として、農薬の使用が挙げられている。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 0, '["本文に「原因として農薬の使用や生息環境の変化、さらには気候の変動などが挙げられている」とある。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9202);
