INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '江戸時代の贈答文化', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

江戸時代、人々は季節の節目に贈り物を交わす習慣を大切にしていた。中元や歳暮といった行事はその代表例で、日頃お世話になっている相手への感謝を形にする機会として広く定着した。当時の贈答品には食品や日用品が選ばれることが多く、贈る側の心遣いが重視されたという。特に中元は、盆の時期に先祖を供養する行事と結びついて広まったとされ、庶民の間にも次第に浸透していった。商人の間では、取引先との関係を良好に保つための重要な慣習としても位置づけられていたという。この習慣は明治以降も形を変えながら続き、現代の贈答文化の基盤になっているとも言われる。もっとも、贈答の形式や品物は時代とともに変化しており、当時とまったく同じ習慣が今も残っているわけではない。近年では、簡素化を志向する家庭も増え、贈答文化そのものの意味も少しずつ変わりつつあるようだ。

【設問】
中元は盆の時期に先祖を供養する行事と結びついて広まったとされる。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 0, '["本文に「中元は、盆の時期に先祖を供養する行事と結びついて広まったとされ」とある。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9203);
