INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', 'コーヒーの歴史', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

コーヒーの起源には諸説あるが、アフリカのある地域で山羊がコーヒーの実を食べて興奮している様子を見た人が、その効果に気づいたという逸話が広く知られている。その後コーヒーは中東を経てヨーロッパへと伝わり、各地で独自の飲み方や文化が発展したとされる。ヨーロッパでは、コーヒーハウスが知識人たちの議論の場として栄えた時代もあったという。当時のコーヒーハウスは身分にかかわらず誰もが自由に出入りできる、数少ない社交の場だったとも言われている。日本には江戸時代に伝来したとされるが、一般に広く飲まれるようになったのは明治以降のことである。現在では世界中で消費される飲料となり、生産地の経済にも大きな影響を与えている。生産の多くを担う国々では、コーヒー豆が主要な輸出品となっている場合も多い。ただし気候変動による生産量の減少も懸念されており、将来的な価格の高騰を予測する声もある。

【設問】
コーヒーは中東を経てヨーロッパへ伝わったとされる。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 0, '["本文に「その後コーヒーは中東を経てヨーロッパへと伝わり」とある。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9204);
