INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '睡眠と健康', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

睡眠不足が続くと、集中力の低下や免疫力の低下につながることが知られている。しかし現代社会では仕事や勉強に追われ、十分な睡眠時間を確保できない人が多いという。ある研究では、平日の睡眠不足を週末にまとめて解消しようとしても、体内リズムの乱れは十分に回復しないと報告されている。この状態は俗に「社会的時差ぼけ」とも呼ばれ、平日と休日の起床時間の差が大きいほど、心身への負担も大きくなる傾向があるとされる。慢性的な寝不足は、生活習慣病のリスクを高める要因の一つとも指摘されている。睡眠の質を高めるためには、就寝前のスマートフォン使用を控える、規則正しい起床時間を保つといった工夫が有効とされる。健康的な生活を送るうえで、睡眠は食事や運動と同様に重要な要素だといえるだろう。企業の中には、社員の睡眠改善を支援する研修を導入するところも出てきている。

【設問】
平日の睡眠不足は、週末にまとめて解消すれば体内リズムも十分に回復する。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 1, '["本文では「週末にまとめて解消しようとしても、体内リズムの乱れは十分に回復しない」とされており、逆の内容である。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9205);
