INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', 'ヒートアイランド現象', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

夏になると都市部の気温が郊外に比べて高くなる現象は、ヒートアイランド現象と呼ばれる。アスファルトやコンクリートが日中の熱を蓄え、夜間も気温が下がりにくくなることが主な原因とされる。加えて、エアコンの室外機から排出される熱も、都市部の気温上昇に拍車をかけていると考えられている。この現象により熱中症のリスクが高まるほか、冷房使用量の増加による電力消費の増大も懸念されている。夜間の気温が下がりにくいことで、睡眠の質にも悪影響を及ぼすとの指摘もある。対策として、屋上緑化や打ち水、街路樹の植栽などが各地で試みられている。一部の自治体では、道路の舗装に遮熱性の高い素材を採用する取り組みも始まっている。もっとも、こうした対策の効果は地域や実施規模によって異なり、一律に評価することは難しい。効果を客観的に検証するため、対策の前後で気温の変化を継続的に測定している自治体もあるという。

