INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', 'キャッシュレス決済', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

キャッシュレス決済は、現金を持ち歩く必要がなく、支払いにかかる時間を短縮できる点で利便性が高いとされる。店舗側にとっても、現金管理の手間が減り、レジ締め作業の負担が軽くなるという利点がある。一方で、通信障害やシステム障害が起きた際には決済ができなくなるリスクも指摘されている。実際に、大規模なシステム障害によって多くの店舗で一時的に決済が行えなくなった事例も報告されている。こうした事態に備え、現金での支払いも並行して受け付ける店舗が多いのが現状である。また、高齢者の中にはスマートフォンの操作に不慣れで、キャッシュレス決済の導入に抵抗を感じる人も一定数存在する。普及を進めるうえでは、利便性の向上だけでなく、誰もが使いやすい仕組みづくりが求められているといえるだろう。操作方法を丁寧に説明する講習会を開く自治体も、少しずつ増えてきているという。

