INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '植物工場と農業', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

近年、天候に左右されずに野菜を安定生産できる植物工場が注目を集めている。室内で光や温度、湿度を管理しながら栽培するため、農薬の使用を抑えられるという利点がある。また、都市部に工場を設置すれば、輸送にかかる時間やコストを削減できる可能性もある。実際に、都市部のビルの一角を利用した植物工場で、レストラン向けの葉物野菜を生産している事例も報告されている。収穫時期を細かく調整できるため、需要にあわせた出荷計画を立てやすいという利点もあるという。一方で、設備投資や運用にかかる電気代が高額になりやすく、採算を取ることが難しいという課題も指摘されている。天候不順による露地栽培の不作時には、価格が安定しやすいという利点が評価されることもあるという。今後、技術の進歩によってコストが下がれば、より普及が進むと期待する声もある。

