INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '紅茶の文化史', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

紅茶はもともと中国で生まれた飲み物だが、イギリスに伝わってからは独自の文化として発展したとされる。当初は高級品として貴族の間で楽しまれていたが、次第に価格が下がり、庶民の生活にも広く浸透していったという。午後の決まった時間に紅茶を飲みながら軽食をとる習慣は、19世紀に貴族の間で始まったとされ、今日でも一部の家庭や店で受け継がれている。植民地時代には、イギリスがインドなど各地で茶葉の生産を拡大させ、世界的な貿易品として紅茶が広まる契機となった。この過程では、労働者に対する厳しい環境が問題視されることもあったという。茶葉の栽培には多くの人手が必要とされ、当時の生産地では長時間労働が常態化していたとの指摘もある。こうした歴史を踏まえ、近年では生産者に適正な対価が支払われているかを認証する制度を取り入れる紅茶ブランドも増えてきているという。一杯の紅茶を選ぶことが、遠い産地の暮らしにもつながっているという意識が、消費者の間にも徐々に広がりつつあるとされる。現在では、産地や製法によってさまざまな種類の紅茶が楽しまれており、飲み方も国や地域によって多様である。紅茶一杯の背景には、貿易や労働をめぐる複雑な歴史が横たわっているといえるだろう。

