INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '自動運転技術', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

自動運転技術は、センサーやカメラで周囲の状況を認識し、人の操作なしに車両を走行させる技術として開発が進められている。交通事故の多くは人的ミスが原因とされており、自動運転が普及すれば事故件数の減少が期待されるという。実際に、高速道路など限定された条件下では、すでに一定レベルの自動運転機能を搭載した車両が実用化されている。一方で、複雑な市街地や悪天候下での走行には、まだ技術的な課題が残されているとされる。歩行者や自転車が予測しにくい動きをした場合の対応精度が、実用化における大きな壁になっているという指摘もある。特に、狭い路地や信号のない交差点では、人の判断に頼らざるを得ない場面がまだ多く残っているとされる。開発企業の中には、実際の交通環境を模した試験コースで、繰り返し走行データを収集しているところもあるという。安全性を積み重ねて実証していく過程が、社会からの信頼を得るためにも欠かせないといえるだろう。実用化のペースは地域や国によっても異なり、一律に語ることは難しい状況にある。また、事故が起きた際の責任の所在をどう定めるかという法整備の課題も残されている。完全な自動運転が実現するまでには、技術面だけでなく制度面の整備も必要だといえるだろう。

【設問】
