INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '育児休業制度', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

育児休業制度は、子どもが生まれた後の一定期間、仕事を休んで育児に専念できるよう定められた制度である。近年は男性の取得を促進する動きが広がっており、法律上の制度も段階的に整備されてきたという。しかし、実際に育児休業を取得した男性社員の割合は、女性に比べて依然として低い水準にとどまっているとされる。取得をためらう理由として、職場の理解不足や、休業中の収入減少への不安などが挙げられている。一方で、育児休業を積極的に取得した男性社員からは、家庭での役割分担を見直すきっかけになったという声も聞かれるという。企業の中には、上司が率先して育児休業を取得することで、取得しやすい雰囲気づくりを進めているところもある。休業中の業務を引き継ぐための体制づくりを事前に整えておくことも、円滑な取得のために重要だとされる。取得した社員へのアンケートでは、育児休業をきっかけに家事や育児への関わり方が変わったと答えた人が多かったという。制度の充実と職場の意識改革を両輪で進めることが、今後も求められるといえるだろう。数字上の制度整備だけでなく、実際に休みやすい空気をどう作るかが問われている。制度が整っているだけでは十分でなく、実際に利用しやすい職場環境づくりが今後の課題として挙げられている。

【設問】
育児休業を取得した男性社員の割合は、女性に比べて依然として低い水準にとどまっている。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 0, '["本文に「育児休業を取得した男性社員の割合は、女性に比べて依然として低い水準にとどまっている」とある。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9232);
