INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '賞味期限と消費期限', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

食品パッケージに記載される「賞味期限」と「消費期限」は、混同されやすいが意味が異なる表示である。賞味期限はおいしく食べられる期限の目安であり、期限を過ぎてもすぐに食べられなくなるわけではないとされる。一方、消費期限は安全に食べられる期限を示すもので、傷みやすい食品に表示されることが多いという。この違いが十分に理解されていないことが、まだ食べられる食品を必要以上に廃棄してしまう一因になっているとの指摘もある。実際に、賞味期限を過ぎた食品の多くは、外見やにおいに問題がなければ食べられる場合が多いという専門家の見解もある。こうした状況を受け、賞味期限の表示をこれまでより長めの年月単位に変更する食品メーカーも出てきている。年月単位での表示に切り替えることで、店舗での在庫管理の手間が軽減されるという副次的な効果も報告されているという。消費者庁なども、期限表示の意味を正しく伝えるための啓発資料を作成し、周知に努めているとされる。表示制度と消費者の理解の両面から、食品ロスの削減に取り組む動きが進んでいるといえるだろう。期限表示の正しい理解を広めることは、食品ロスの削減にもつながる取り組みだといえるだろう。

