INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '養殖漁業', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

養殖漁業は、天然の漁獲量が世界的に不安定化する中で、水産物の安定供給を支える手段として重要性を増しているとされる。魚の成長段階を管理しながら育てられるため、計画的な出荷が可能になるという利点がある。一方で、狭い生けすで多くの魚を育てることにより、病気が発生しやすくなるという課題も指摘されている。この対策として、抗生物質の使用が問題視される場合もあり、環境や食の安全への配慮を求める声が強まっているという。近年では、魚の排せつ物を活用して植物を育てる循環型の養殖技術も開発が進められている。この技術は、水を浄化しながら養殖と農業を同時に行える点が評価されており、環境負荷の低減にもつながると期待されている。導入コストが従来の養殖方式より高くなる場合が多く、普及にはまだ時間がかかるとの見方もあるという。実証実験を行う施設では、育てられる魚の種類や規模を徐々に広げる試みが続けられているとされる。安定した供給と環境への配慮を両立させる技術として、今後の普及が注目されているが、コスト面での改善が普及の鍵を握っているとの見方が大勢を占めている。養殖漁業が持続可能な形で発展していくためには、生産性の向上と環境保全を両立させる工夫が欠かせないといえるだろう。

【設問】
