INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '昆虫食', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

昆虫食は、将来の食料問題を解決する手段の一つとして、近年国内外で注目を集めている。昆虫は牛や豚に比べて、同じ量のたんぱく質を得るために必要な飼料や水、土地の面積が少なくて済むとされ、環境負荷の低い食料源として期待されているという。実際に、コオロギなどを原料としたクッキーやスナック菓子が商品化され、販売されている例もある。一方で、見た目への抵抗感から、昆虫食に対して心理的なハードルを感じる消費者が多いことも事実である。この課題に対応するため、粉末状に加工して原形をわかりにくくする工夫を凝らした商品開発が進められているという。また、特定の昆虫にアレルギーを持つ人がいることも指摘されており、安全性に関する情報提供の重要性も高まっている。生産者の間では、衛生管理を徹底した専用の飼育施設を整備し、安定した品質を保つ取り組みも進められているという。将来的には、家畜の飼料に昆虫由来のたんぱく質を活用する研究も進んでおり、食料生産全体を支える技術として期待されている。世界の人口増加が続く中、限られた資源で食料を確保する手段として、今後も研究の進展が注目されるだろう。昆虫食が一般家庭の食卓に定着するには、味や価格だけでなく、心理的な抵抗感をどう和らげるかが鍵になるといえるだろう。

