INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '外来種問題', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

外来種とは、本来その地域には生息していなかったが、人間の活動によって別の地域から持ち込まれた生物を指す。ペットとして飼われていた動物が野生化したり、輸入された荷物に紛れて意図せず運ばれたりすることが、外来種が広がる主な経路とされる。外来種の中には、在来の生物を捕食したり、生息場所を奪ったりすることで、地域の生態系のバランスを崩してしまう種も存在するという。こうした被害を防ぐため、特定の外来種の飼育や輸入を規制する法律が定められている国も多い。すでに定着してしまった外来種を完全に駆除することは非常に難しく、多大な費用と時間がかかる場合が多いとされる。一部の地域では、住民が協力して外来植物の除去作業を行うボランティア活動も行われているという。専門家は、駆除活動を単発で終わらせず、継続的に行うことが生態系の回復には不可欠だと指摘している。輸入品の検疫体制を強化し、外来種の侵入を水際で防ぐ取り組みも各国で進められているとされる。一人ひとりが安易に生き物を野外に放さないという意識を持つことも、被害を防ぐうえで欠かせないといえるだろう。生態系を守るためには、新たな外来種を持ち込まないという予防的な取り組みが、最も効果的な対策の一つだと考えられている。

【設問】
