INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', 'ペーパーレス化・電子契約', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

企業や行政機関では、紙の書類をやり取りする代わりに、電子データで契約や手続きを完結させるペーパーレス化が進められている。電子契約は、印紙税の負担を軽減できるほか、郵送にかかる時間を省略できる点が利点として挙げられるという。また、書類を保管するための物理的なスペースが不要になることも、企業にとってはコスト削減につながるとされる。一方で、電子データの改ざんを防ぐためのセキュリティ対策や、取引先が電子契約に対応していない場合の調整など、導入にあたっての課題も存在する。特に中小企業では、システム導入にかかる初期費用が負担となり、導入が進みにくいという指摘もある。行政の手続きにおいても、押印を廃止し、オンラインで完結できる手続きを増やす動きが各地で見られるという。高齢の利用者からは、オンライン手続きに不慣れで戸惑うという声も上がっており、窓口対応を併存させる自治体も多い。システムの導入だけでなく、利用者に寄り添った移行期間の支援も課題として挙げられている。紙と電子の両方を選べる仕組みを一定期間残すことが、円滑な移行の助けになるとの見方もある。ペーパーレス化を円滑に進めるためには、制度の整備と併せて、利用者側の理解と対応力を高めていくことが欠かせないといえるだろう。

【設問】
電子契約は、印紙税の負担を軽減できる利点があるとされる。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 0, '["本文に「電子契約は、印紙税の負担を軽減できる」とある。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9244);
