INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_verbal', '論理的読解', '動物園の役割', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

動物園は、動物を展示して来園者に見てもらう場としての役割だけでなく、絶滅の危機にある種を保護し、繁殖させる役割も担っているとされる。飼育下での繁殖に成功した個体を、将来的に野生に戻す取り組みを行っている施設もあるという。また、来園者が動物の生態や生息環境について学べるよう、解説板や体験型のプログラムを充実させる動物園も増えている。一方で、限られた飼育スペースの中で動物を育てることが、動物にとってストレスになるのではないかという意見も根強く存在する。この課題に対応するため、動物本来の行動を引き出せるよう、飼育環境を工夫する取り組みが各地で進められているという。実際に、環境を改善したことで、繁殖の成功率が向上した事例も報告されている。飼育員が動物の行動を細かく観察し、日々の記録を積み重ねることが、こうした改善の土台になっているという。学校と連携した出張授業を行い、来園できない子どもたちにも学びの機会を広げる動物園も出てきている。動物との出会いを通じて、命の大切さや自然環境への関心を育む場として、動物園の役割はこれからも広がっていくと考えられる。動物園は、娯楽施設としての側面と、種の保存や環境教育を担う施設としての側面を、あわせ持つ存在だといえるだろう。

【設問】
動物園は絶滅の危機にある種を保護し、繁殖させる役割も担っているとされる。', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている","本文の内容から明らかに間違っている、または間違った内容が含まれている","本文の内容からは、正しいか間違っているか判断できない"]', 0, '["本文に「絶滅の危機にある種を保護し、繁殖させる役割も担っているとされる」とある。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 言語理解/論理的読解）', 9250);
